      "title": "Parsed Query",
      "type": "string"
    }
  },
  "required": [
    "image_files_path",
    "query",
    "parsed_query"
  ],
  "type": "object"
}
Returns: A tuple containing: 'path_to_scores_json, path_to_ranked_image_files_json'.
------------------------------
